 const [busy,setBusy]=useState(false),[message,setMessage]=useState(""),[tab,setTab]=useState<"bookings"|"history"|"calendar"|"barbers"|"finance"|"reports"|"services"|"staff"|"website">("bookings");
 const [calendarDate,setCalendarDate]=useState(new Date().toLocaleDateString("en-CA")),[calendarMode,setCalendarMode]=useState<"day"|"week"|"month">("week"),[calendarBarber,setCalendarBarber]=useState("all");
